/* Wishlist navigation: the sidebar link opens the already-approved analysis
   without inserting standalone cards between level panels. */
(function () {
  function dialogFromHref(href) {
    if (!href || !/^#wishlist-nivel-\d+$/.test(href)) return null;
    const el = document.getElementById(href.slice(1));
    return el && el.matches('dialog.duncan-wishlist-dialog') ? el : null;
  }
  document.addEventListener('click', function (ev) {
    const a = ev.target.closest('a[data-wishlist-open]');
    if (a) {
      const dlg = dialogFromHref(a.getAttribute('href'));
      if (dlg && dlg.showModal) {
        ev.preventDefault();
        if (!dlg.open) dlg.showModal();
        return;
      }
    }
    const close = ev.target.closest('[data-wishlist-close]');
    if (close) {
      const dlg = close.closest('dialog.duncan-wishlist-dialog');
      if (dlg) dlg.close();
    }
    const goBack = ev.target.closest('a.dw-back-to-level');
    if (goBack) {
      const dlg = goBack.closest('dialog.duncan-wishlist-dialog');
      if (dlg) dlg.close();
    }
  });
  document.addEventListener('click', function (ev) {
    if (ev.target.matches('dialog.duncan-wishlist-dialog')) {
      const r = ev.target.getBoundingClientRect();
      if (ev.clientX < r.left || ev.clientX > r.right || ev.clientY < r.top || ev.clientY > r.bottom) ev.target.close();
    }
  });
  function openDirectLink() {
    const dlg = dialogFromHref(window.location.hash);
    if (dlg && dlg.showModal && !dlg.open) dlg.showModal();
  }
  window.addEventListener('hashchange',openDirectLink);
  window.addEventListener('DOMContentLoaded',openDirectLink);
})();


(() => {
  'use strict';
  /* FORJA NAV — adaptação de navegação 1–20 de Voldemort para Duncan.
     Fonte: plugins/forja-mineira-builds/assets/js/builds.js (produção).
     Não duplica a navegação anterior/próximo, já presente na v1.9.
     O mascote acompanha o scroll e pode ser arrastado sobre a barra para escolher o nível. */
  const phases = [
    { roman: 'I', name: 'Os Primeiros Passos', short: 'Primeiros Passos', start: 1, end: 4 },
    { roman: 'II', name: 'O Cavaleiro Protetor', short: 'Cavaleiro Protetor', start: 5, end: 8 },
    { roman: 'III', name: 'O Guardião da Estrada', short: 'Guardião da Estrada', start: 9, end: 12 },
    { roman: 'IV', name: 'A Honra como Escudo', short: 'Honra como Escudo', start: 13, end: 16 },
    { roman: 'V', name: 'A Fortaleza Viva', short: 'Fortaleza Viva', start: 17, end: 20 }
  ];
  const mascot = 'data:image/png;base64,';
  const clamp = (value,min,max) => Math.min(max,Math.max(min,value));

  function init() {
    const root = document.querySelector('#forja-build-duncan.fmb-build-root--duncan');
    if (!root || root.dataset.duncanNavReady === '1') return;
    const sections = Array.from({length:20}, (_,i) => root.querySelector('#nivel-'+(i+1)));
    if (sections.some(x => !x)) return;
    root.dataset.duncanNavReady = '1';
    const goto = level => {
      const target = level === 0 ? root : sections[level-1];
      if (target) target.scrollIntoView({behavior:'smooth',block:'start'});
    };
    const phaseFor = level => phases.find(p => p.start<=level && level<=p.end) || phases[0];
    const levelTitle = level => {
      const h1 = sections[level-1]?.querySelector('h1');
      return h1?.textContent?.replace(/\s+/g,' ').trim() || `Nível ${level}`;
    };

    const shell = document.createElement('div');
    shell.id = 'duncan-forja-nav-v2';
    shell.className = 'fmb-nav-shell';
    shell.innerHTML = `
      <nav class="fmb-journey-dock" aria-label="Navegação rápida da build de Duncan">
        <div class="fmb-dock-status" aria-live="polite">
          <span class="fmb-dock-phase">Fase I · Os Primeiros Passos</span>
          <span class="fmb-dock-level">Nível 1 de 20</span>
        </div>
        <div class="fmb-progress-wrap" role="slider" tabindex="0" aria-label="Pão de Queijo D20: escolha o nível" aria-valuemin="1" aria-valuemax="20" aria-valuenow="1" aria-valuetext="Nível 1 de 20. Arraste o pão de queijo para navegar.">
          <div class="fmb-progress-track"><span class="fmb-progress-fill"></span></div>
          <img class="fmb-progress-cheese" src="${mascot}" alt="" width="34" height="34" draggable="false">
        </div>
        <button class="fmb-level-menu-toggle" type="button" aria-expanded="false" aria-controls="duncan-forja-level-menu">Ir para o nível ▾</button>
        <div class="fmb-level-menu" id="duncan-forja-level-menu" aria-hidden="true">
          <div class="fmb-level-menu-head">
            <strong>Escolha onde continuar</strong>
            <button class="fmb-level-menu-close" type="button" aria-label="Fechar menu">×</button>
          </div>
          <div class="fmb-phase-jumps"></div>
          <div class="fmb-level-grid"></div>
          <p class="fmb-level-menu-tip">Arraste o Pão de Queijo D20 na linha para escolher um nível; ao soltar, a página salta até ele.</p>
        </div>
      </nav>`;

    const topLine = document.createElement('div');
    topLine.className = 'fmb-scroll-line';
    topLine.setAttribute('aria-hidden', 'true');
    topLine.innerHTML = '<span></span>';

    const backTop = document.createElement('button');
    backTop.type = 'button';
    backTop.className = 'fmb-backtop';
    backTop.setAttribute('aria-label','Voltar ao topo da build de Duncan');
    backTop.innerHTML = `
      <img src="${mascot}" alt="" width="58" height="58">
      <span class="fmb-backtop-arrow" aria-hidden="true">↑</span>
      <span class="fmb-backtop-label">Voltar à forja</span>`;

    document.body.append(topLine,shell,backTop);

    const menu = shell.querySelector('.fmb-level-menu');
    const toggle = shell.querySelector('.fmb-level-menu-toggle');
    const close = shell.querySelector('.fmb-level-menu-close');
    const phaseWrap = shell.querySelector('.fmb-phase-jumps');
    const levelGrid = shell.querySelector('.fmb-level-grid');
    const phaseLabel = shell.querySelector('.fmb-dock-phase');
    const levelLabel = shell.querySelector('.fmb-dock-level');
    const cheese = shell.querySelector('.fmb-progress-cheese');
    const scrub = shell.querySelector('.fmb-progress-wrap');
    const track = shell.querySelector('.fmb-progress-track');

    const closeMenu = () => {
      menu.classList.remove('is-open');menu.setAttribute('aria-hidden','true');
      toggle.setAttribute('aria-expanded','false');toggle.textContent='Ir para o nível ▾';
    };
    const openMenu = () => {
      menu.classList.add('is-open');menu.setAttribute('aria-hidden','false');
      toggle.setAttribute('aria-expanded','true');toggle.textContent='Fechar níveis ×';
    };

    phases.forEach(phase => {
      const b = document.createElement('button');b.type='button';b.className='fmb-phase-jump';
      b.dataset.phaseStart = String(phase.start);
      b.innerHTML=`<strong>${phase.roman}</strong><span>${phase.short}</span>`;
      b.setAttribute('aria-label',`Ir para a fase ${phase.roman}: ${phase.name}`);
      b.addEventListener('click',()=>{goto(phase.start);closeMenu();});
      phaseWrap.appendChild(b);
    });
    for(let level=1;level<=20;level++){
      const b=document.createElement('button');b.type='button';b.textContent=String(level);
      b.dataset.level=String(level);
      b.setAttribute('aria-label',`Ir para o nível ${level}: ${levelTitle(level)}`);
      b.addEventListener('click',()=>{goto(level);closeMenu();});
      levelGrid.appendChild(b);
    }
    toggle.addEventListener('click',()=>menu.classList.contains('is-open')?closeMenu():openMenu());
    close.addEventListener('click',closeMenu);
    document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeMenu();});
    document.addEventListener('click',ev=>{
      if(menu.classList.contains('is-open')&&!shell.contains(ev.target))closeMenu();
    });
    backTop.addEventListener('click',()=>goto(0));

    let currentLevel=1, raf=0, isScrubbing=false;
    function update(){
      raf=0;
      if (isScrubbing) return;
      const viewportPoint=window.innerHeight*.36;
      let nextLevel=1,active=sections[0];
      sections.forEach((section,index)=>{
        if(section.getBoundingClientRect().top<=viewportPoint){nextLevel=index+1;active=section;}
      });
      const rect=active.getBoundingClientRect();
      const local=clamp((viewportPoint-rect.top)/Math.max(rect.height,1),0,1);
      const progress=clamp((((nextLevel-1)+local)/20)*100,0,100);
      shell.style.setProperty('--fmb-progress',progress+'%');
      topLine.style.setProperty('--fmb-progress',progress+'%');
      const phase=phaseFor(nextLevel);
      phaseLabel.textContent=`Fase ${phase.roman} · ${phase.name}`;
      levelLabel.textContent=`Nível ${nextLevel} de 20`;
      scrub.setAttribute('aria-valuenow',String(nextLevel));
      scrub.setAttribute('aria-valuetext',`Nível ${nextLevel} de 20. Arraste para navegar.`);
      const entered=sections[0].getBoundingClientRect().top<window.innerHeight*.72;
      shell.classList.toggle('is-visible',entered);
      backTop.classList.toggle('is-visible',entered);
      if(nextLevel!==currentLevel){
        currentLevel=nextLevel;
        cheese.classList.remove('is-bouncing');
        void cheese.offsetWidth;
        cheese.classList.add('is-bouncing');
      }
      levelGrid.querySelectorAll('button').forEach(b=>
        b.classList.toggle('is-current',Number(b.dataset.level)===nextLevel));
      phaseWrap.querySelectorAll('button').forEach(b=>{
        const p=phases.find(p=>p.start===Number(b.dataset.phaseStart));
        b.classList.toggle('is-current',!!p&&p.start<=nextLevel&&nextLevel<=p.end);
      });
    }
    const requestUpdate=()=>{if(!raf)raf=requestAnimationFrame(update);};

    /* DUNCAN-UX-08: a alca e o proprio Pao de Queijo D20.
       Nao e possivel mover o dock nem saltar apenas clicando na linha.
       Mouse, toque e caneta compartilham Pointer Events + captura na alca. */
    let dragPointerId = null;
    let grabOffsetX = 0;
    let originClientX = 0;
    let didMove = false;
    let targetLevel = 1;
    const levelFromFraction = fraction => clamp(Math.round(fraction * 19) + 1, 1, 20);
    const previewFraction = fraction => {
      const progress = clamp(fraction, 0, 1);
      targetLevel = levelFromFraction(progress);
      shell.style.setProperty('--fmb-progress', (progress * 100).toFixed(3) + '%');
      const phase = phaseFor(targetLevel);
      phaseLabel.textContent = `Fase ${phase.roman} · ${phase.name}`;
      levelLabel.textContent = `Solte para ir ao nível ${targetLevel}`;
      scrub.setAttribute('aria-valuenow', String(targetLevel));
      scrub.setAttribute('aria-valuetext', `Solte para ir ao nível ${targetLevel} de 20`);
      levelGrid.querySelectorAll('button').forEach(button =>
        button.classList.toggle('is-current', Number(button.dataset.level) === targetLevel));
      phaseWrap.querySelectorAll('button').forEach(button => {
        const p = phases.find(phase => phase.start === Number(button.dataset.phaseStart));
        button.classList.toggle('is-current', !!p && p.start <= targetLevel && targetLevel <= p.end);
      });
    };
    const moveMarkerWithPointer = event => {
      const rect = track.getBoundingClientRect();
      // Compensa onde o marcador foi agarrado para nao saltar ao pressionar.
      const markerCenterX = event.clientX - grabOffsetX;
      previewFraction((markerCenterX - rect.left) / Math.max(rect.width, 1));
    };
    cheese.addEventListener('pointerdown', event => {
      if (dragPointerId !== null || !event.isPrimary ||
          (event.pointerType === 'mouse' && event.button !== 0)) return;
      isScrubbing = true;
      // Suspende a animacao de progresso antes de medir o ponto de pegada.
      scrub.classList.add('is-scrubbing');
      const marker = cheese.getBoundingClientRect();
      grabOffsetX = event.clientX - (marker.left + marker.width / 2);
      originClientX = event.clientX;
      dragPointerId = event.pointerId;
      didMove = false;
      // A captura na imagem mantem o marcador sob o cursor mesmo fora da barra.
      cheese.setPointerCapture(event.pointerId);
      event.preventDefault();
      event.stopPropagation();
    });
    cheese.addEventListener('pointermove', event => {
      if (!isScrubbing || event.pointerId !== dragPointerId) return;
      if (Math.abs(event.clientX - originClientX) >= 4) didMove = true;
      if (didMove) moveMarkerWithPointer(event);
      event.preventDefault();
    });
    const finishMarkerDrag = (event, commit) => {
      if (!isScrubbing || event.pointerId !== dragPointerId) return;
      if (Math.abs(event.clientX - originClientX) >= 4) didMove = true;
      if (didMove && commit) moveMarkerWithPointer(event);
      const selected = targetLevel;
      const shouldNavigate = commit && didMove;
      const capturedId = dragPointerId;
      dragPointerId = null;
      isScrubbing = false;
      didMove = false;
      scrub.classList.remove('is-scrubbing');
      if (cheese.hasPointerCapture?.(capturedId)) cheese.releasePointerCapture(capturedId);
      if (shouldNavigate) {
        closeMenu();
        // Salto direto: evita uma longa animacao quando o destino esta longe.
        sections[selected - 1].scrollIntoView({behavior:'instant',block:'start'});
      }
      requestUpdate();
      event.preventDefault();
    };
    cheese.addEventListener('pointerup', event => finishMarkerDrag(event, true));
    cheese.addEventListener('pointercancel', event => finishMarkerDrag(event, false));
    cheese.addEventListener('lostpointercapture', () => {
      if (isScrubbing) {
        isScrubbing = false;
        dragPointerId = null;
        didMove = false;
        scrub.classList.remove('is-scrubbing');
        requestUpdate();
      }
    });
    cheese.addEventListener('dragstart', event => event.preventDefault());
    scrub.addEventListener('keydown',ev=>{
      const current=Number(scrub.getAttribute('aria-valuenow'))||1;
      let next=current;
      if(ev.key==='ArrowRight'||ev.key==='ArrowUp')next=Math.min(20,current+1);
      else if(ev.key==='ArrowLeft'||ev.key==='ArrowDown')next=Math.max(1,current-1);
      else if(ev.key==='Home')next=1;
      else if(ev.key==='End')next=20;
      else return;
      ev.preventDefault();
      targetLevel=next;
      goto(next);
      // Atualizar o valor acessível mesmo antes do término da rolagem suave.
      scrub.setAttribute('aria-valuenow',String(next));
    });
    window.addEventListener('scroll',requestUpdate,{passive:true});
    window.addEventListener('resize',requestUpdate);
    window.addEventListener('pageshow',requestUpdate);
    update();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});
  else init();
})();

